        override
        returns (bool freeze, bytes32 targetCodeHash, uint64 revision, bytes32 stateHash)
    {
        (freeze, targetCodeHash, revision, stateHash) =
            StreamGovernancePolicy.freezeConfig(_policy, _admin, target, selector);
    }
